         FONT _residential_font
         SIZE _residential_lbl_size
         COLOR _residential_lbl_clr
         WRAP ' '
         MAXLENGTH 6
         ALIGN CENTER
         MINFEATURESIZE AUTO
         PARTIALS FALSE
