#if _display_transport_areas == 1
LAYER
   TYPE POLYGON
   STATUS ON
   PROJECTION
       "init=epsg:OSM_SRID"
   END
   NAME layername(transport_areas,_layer_suffix)
   GROUP "default"
   CONNECTIONTYPE POSTGIS
   CONNECTION "OSM_DB_CONNECTION"
#if OSM_FORCE_POSTGIS_EXTENT == 1
    EXTENT OSM_EXTENT
#endif
   COMPOSITE
     OPACITY _transport_opacity
   END # COMPOSITE
   DATA "geometry from OSM_SCHEMA.OSM_PREFIX_transport_areas using unique osm_id using srid=OSM_SRID"
   PROCESSING "CLOSE_CONNECTION=DEFER"
   MAXSCALEDENOM _maxscale
   MINSCALEDENOM _minscale
   LABELITEM "name"
   CLASS
      STYLE
         COLOR _transport_clr
      END
#if _display_transport_lbl==1
      LABEL
        TYPE TRUETYPE
        PARTIALS FALSE
        FONT _transport_font
        SIZE _transport_lbl_size
        COLOR _transport_lbl_clr
        PRIORITY 1
        WRAP ' '
        MAXLENGTH 6
        ALIGN CENTER
        MINFEATURESIZE AUTO
      END
#endif
   END
END

#endif

LAYER
    TYPE POLYGON
    STATUS ON
    PROJECTION
        "init=epsg:OSM_SRID"
    END
    NAME layername(waterarea,_layer_suffix)
    GROUP "default"
    CONNECTIONTYPE POSTGIS
    CONNECTION "OSM_DB_CONNECTION"
#if OSM_FORCE_POSTGIS_EXTENT == 1
    EXTENT OSM_EXTENT
#endif
    COMPOSITE
      OPACITY _waterarea_opacity
    END # COMPOSITE
    DATA _waterarea_data
    MAXSCALEDENOM _maxscale
    MINSCALEDENOM _minscale
    PROCESSING "CLOSE_CONNECTION=DEFER"
    LABELITEM "name"
    CLASSITEM "type"
    CLASS
      EXPRESSION "riverbank"
        STYLE
            COLOR _waterarea_clr
        END
    END
    CLASS
        STYLE
            COLOR _waterarea_clr
        END
#if _display_waterarea_lbl == 1
        LABEL
          TYPE TRUETYPE
          PARTIALS FALSE
          FONT _waterarea_font
          MINDISTANCE 200
          SIZE _waterarea_lbl_size
          ENCODING "utf-8"
          COLOR _waterarea_lbl_clr
          WRAP ' '
          MAXLENGTH 5
          ALIGN CENTER
          MINFEATURESIZE AUTO
        END
#endif
    END
END

#if _display_waterways == 1
LAYER
    TYPE LINE
    NAME layername(waterways,_layer_suffix)
    STATUS ON
    GROUP "default"
    CONNECTIONTYPE POSTGIS
    CONNECTION "OSM_DB_CONNECTION"
#if OSM_FORCE_POSTGIS_EXTENT == 1
    EXTENT OSM_EXTENT
#endif
    COMPOSITE
      OPACITY _waterways_opacity
    END # COMPOSITE
    DATA _waterways_data
    CLASSITEM "type"
    MAXSCALEDENOM _maxscale
    MINSCALEDENOM _minscale
    LABELITEM "name"
    PROJECTION
        "init=epsg:OSM_SRID"
    END
    PROCESSING "CLOSE_CONNECTION=DEFER"
    CLASS
        EXPRESSION "river"
        STYLE
            COLOR _river_clr
            WIDTH _river_width
        END
#if _display_river_lbl == 1
        LABEL
          TYPE TRUETYPE
          PARTIALS FALSE
          FONT _river_font
          MINDISTANCE 200
          SIZE _river_lbl_size
          COLOR _river_lbl_clr
          REPEATDISTANCE 400
          ENCODING "utf-8"
          MINFEATURESIZE AUTO
          ANGLE FOLLOW
          BUFFER 3
        END
#endif
    END
    CLASS
        EXPRESSION "stream"
        STYLE
            COLOR _stream_clr
            WIDTH _stream_width
        END
#if _display_stream_lbl == 1
        LABEL
          TYPE TRUETYPE
          PARTIALS FALSE
          FONT _stream_font
          MINDISTANCE 200
            REPEATDISTANCE 400
          SIZE _stream_lbl_size
          COLOR _stream_lbl_clr
          MINFEATURESIZE AUTO
       ENCODING "utf-8"
          ANGLE FOLLOW
          BUFFER 3
        END
#endif
    END
    CLASS
        EXPRESSION "canal"
        STYLE
            COLOR _canal_clr
            WIDTH _canal_width
        END
#if _display_canal_lbl == 1
        LABEL
          TYPE TRUETYPE
          FONT _canal_font
          MINDISTANCE 200
            REPEATDISTANCE 400
          SIZE _canal_lbl_size
          ENCODING "utf-8"
          COLOR _canal_lbl_clr
          MINFEATURESIZE AUTO
          ANGLE FOLLOW
          BUFFER 3
          PARTIALS FALSE
        END
#endif
    END
END
#endif

