      END
    END
  END


#if _display_landuse_outlines == 1
## Couche affichant les bordures de toutes les surfaces landuse par-dessus les autres éléments
## Cette couche est rendue en dernier pour garantir que les bordures soient visibles au-dessus de toutes les surfaces
LAYER
    TYPE POLYGON
    STATUS ON
    PROJECTION
        "init=epsg:OSM_SRID"
    END
    NAME layername(landuse_outlines,_layer_suffix)
    GROUP "default"
    CONNECTIONTYPE POSTGIS
    CONNECTION "OSM_DB_CONNECTION"
  #if OSM_FORCE_POSTGIS_EXTENT == 1
    EXTENT OSM_EXTENT
  #endif
    DATA _landusage_data
    PROCESSING "CLOSE_CONNECTION=DEFER"
    MAXSCALEDENOM _maxscale
    MINSCALEDENOM _minscale
    CLASSITEM "type"
#if _display_residential_outline == 1
    CLASS
      EXPRESSION 'residential'
      STYLE
         OUTLINECOLOR _residential_ol_clr
         OUTLINEWIDTH _residential_ol_width
      END
    END
#endif
#if _display_parking_outline == 1
    CLASS
      EXPRESSION 'parking'
      STYLE
         OUTLINECOLOR _parking_ol_clr
         OUTLINEWIDTH _parking_ol_width
      END
    END
#endif
#if _display_commercial_outline == 1
    CLASS
      EXPRESSION 'commercial'
      STYLE
         OUTLINECOLOR _commercial_ol_clr
         OUTLINEWIDTH _commercial_ol_width
      END
    END
#endif
#if _display_industrial_outline == 1
    CLASS
      EXPRESSION 'industrial'
      STYLE
         OUTLINECOLOR _industrial_ol_clr
         OUTLINEWIDTH _industrial_ol_width
      END
    END
#endif
#if _display_grass_outline == 1
    CLASS
      EXPRESSION {grassland,meadow,grass,village_green,garden}
      STYLE
         OUTLINECOLOR _grass_ol_clr
         OUTLINEWIDTH _grass_ol_width
      END
    END
#endif
#if _display_farmland_outline == 1
    CLASS
